  const GEMS = [{"id": "gem-tropezienne", "pattern": "tropézienne", "tag": "Gulf gem · born here", "name": "A cake named by a film star", "story": "Alexandre Micka, a Polish-born pastry-maker, settled in Saint-Tropez after the war with a family recipe for a sugar-crusted brioche filled with cream. In 1955 he was catering the shoot of Et Dieu… créa la femme and served it to Brigitte Bardot, who is said to have suggested he name it for the town. The name Tarte Tropézienne was registered later as a trademark.", "where": "La Tarte Tropézienne, the house Micka founded, in Saint-Tropez, over the capes."}, {"id": "gem-marron", "pattern": "marrons glacés", "tag": "Maures gem · grown here", "name": "The chestnut with one kernel", "story": "The Maures carry a chestnut forest of some two thousand hectares, with Collobrières as its capital. The prized nut is the marron: a selected chestnut that fills its burr with a single round kernel instead of several partitioned ones, which is what lets it be candied whole. It becomes crème de marrons and marrons glacés in the village confectioners, and has its own Sundays every October.", "where": "The confectioners of Collobrières, forty minutes inland."}, {"id": "gem-tibouren", "pattern": "Tibouren", "tag": "Peninsula gem · grown here", "name": "The old grape of the capes", "story": "Tibouren is the peninsula’s heritage grape: savoury, faintly orange-tinged, smelling of garrigue rather than candied fruit, and long tied to this stretch of the Saint-Tropez coast. Most growers dropped it for easier varieties; a few estates of the gulf still make it the heart of a rosé, and it is the one to ask for by name.", "where": "The estates of the peninsula; ask for it at the cellar door."}];
  const TABLES = {"grande": {"title": "Les Grandes Tables", "desc": "The tables you clear an evening for: the starred rooms of the peninsula, and two chefs who left the palace kitchens for rooms of their own.", "sections": [{"label": "The stars of the peninsula", "desc": "Two stars on the Ramatuelle cliff, one under the palms of Château de Valmer, and the Starck hotel’s dining room above Gigaro.", "ids": ["v-la-voile-la-reserve-ramatuelle", "v-la-palmeraie-chateau-de-valmer", "v-vista-lily-of-the-valley"]}, {"label": "Out of the palace kitchens — two chefs' rooms", "desc": "A La Vague d’Or pastry chef’s village room in La Croix-Valmer, and the reborn Hôtel du Parc in Cavalaire.", "ids": ["v-les-saisonniers", "v-le-parc-l-hotel-du-parc"]}]}, "petite": {"title": "Les Petites Tables", "desc": "Where this guide actually lives: the tables on the sand, the fish by the water, the corniche, and the hill villages.", "sections": [{"label": "On the sand — Gigaro and the Grande Plage", "desc": "Gigaro’s one-toque beach table, the family of Marius on the same sand, and lunch under straw on Cavalaire’s Grande Plage.", "ids": ["v-la-pinede-plage", "v-marius-a-la-plage", "v-tamaris-beach"]}, {"label": "Fish by the water — the port, the cliff, the pines", "desc": "Aïoli on the Nouveau Port, bouillabaisse on the cliff over the Cron cove, and the catch under the pines of Gigaro since 1964.", "ids": ["v-le-comptoir-des-saveurs", "v-le-grand-bleu-hotel-de-la-cala", "v-le-refuge"]}, {"label": "Along the Corniche des Maures", "desc": "Dédé’s bouillabaisse at Le Rayol, and lunch inside the garden of the Mediterraneans.", "ids": ["v-maurin-des-maures", "v-le-cafe-des-jardiniers-domaine"]}, {"label": "The hill villages — Gassin and Ramatuelle", "desc": "The Bib Gourmand on Gassin’s rampart, a family table in the vines since 1979, and Italy cooked straight in Ramatuelle.", "ids": ["v-bello-visto", "v-la-verdoyante", "v-la-forge"]}]}, "street": {"title": "La Rue — The Street", "desc": "On foot and standing: the boats on the quay, the Wednesday market, and the port bar at sundown.", "sections": [{"label": "La Rue — off the boat, the Wednesday market, the port glass", "desc": "The fishermen’s crates on the Quai Marc Pajot, the Wednesday square, and the mojito on the port.", "ids": ["v-pecheurs-du-port", "v-marche-place-jean-moulin", "v-o-petit-bar"]}]}};
  const CATEGORIES = [{"key": "summit", "label": "The stars of the peninsula", "lead": "Two stars on the Ramatuelle cliff, one under the palms of Château de Valmer, and the Starck hotel’s dining room above Gigaro.", "story": {"title": "Stars above the bay", "story": "The decorated tables around Cavalaire all sit inside hotels, and all three keep summer hours. La Voile, at La Réserve Ramatuelle, has held two stars since 2020 for Éric Canino, a Michel Guérard pupil, and in 2026 opened from 1 May to 11 October. La Palmeraie, on the Château de Valmer wine estate above Gigaro, keeps one star in 2026 and cooks from its own organic garden; it served from 8 May to 4 October, and who signs its menus in 2026 is disputed between the sources. Vista, at Lily of the Valley on the same hillside, has no star but a Gault&Millau 13/20 in 2026, and Sisteron lamb to share.", "where": "La Voile, Ramatuelle; La Palmeraie, La Croix-Valmer; Vista, La Croix-Valmer"}}, {"key": "chefs", "label": "Out of the palace kitchens — two chefs' rooms", "lead": "A La Vague d’Or pastry chef’s village room in La Croix-Valmer, and the reborn Hôtel du Parc in Cavalaire.", "story": {"title": "Two chefs' rooms", "story": "Away from the beaches, two smaller rooms carry their cooks' names more than a view. Les Saisonniers, in La Croix-Valmer village above the municipal pool, opened in early 2024 when Florent Manini, long Arnaud Donckele's pastry chef at La Vague d'Or, and Anna Thillaye went out on their own; despite its name it opens all year, Wednesday to Saturday, and is in the MICHELIN selection. In Cavalaire itself, Le Parc at the renovated Hôtel du Parc is an evening table under the pines where Jean-Brice Ruffroy cooks a southern bistronomic carte; it ran from 24 April to 3 October 2026 and is closed now.", "where": "Les Saisonniers, La Croix-Valmer; Le Parc, Cavalaire-sur-Mer"}}, {"key": "sand", "label": "On the sand — Gigaro and the Grande Plage", "lead": "Gigaro’s one-toque beach table, the family of Marius on the same sand, and lunch under straw on Cavalaire’s Grande Plage.", "story": {"title": "Lunch on the sand", "story": "The bay's beach tables run from spring to autumn and cook what suits a terrace: grilled fish, salads, a pasta. La Pinède Plage, the beach restaurant of a hotel at Gigaro, holds one Gault&Millau toque (12/20, 2025) for an octopus carpaccio, and its 2026 season ran from 30 April to 10 October. At the far end of the same beach, Marius à la plage has been run by Arthur and Sarah since 2012 and grills squid and sardines with house ratatouille; it shut on 30 September. On Cavalaire's Grande Plage, Tamaris Beach serves plancha fish under a straw roof and has the longest season of the three, into late October or early November.", "where": "La Pinède Plage, La Croix-Valmer; Marius à la plage, La Croix-Valmer; Tamaris Beach, Cavalaire-sur-Mer"}}, {"key": "fish", "label": "Fish by the water — the port, the cliff, the pines", "lead": "Aïoli on the Nouveau Port, bouillabaisse on the cliff over the Cron cove, and the catch under the pines of Gigaro since 1964.", "story": {"title": "Fish by Cavalaire's water", "story": "Around Cavalaire the fish tables sit where the boats are, and most of them shut with the season. Le Comptoir des Saveurs, on the Nouveau Port, cooks the Provençal canon of aïoli, daube and pissaladière and keeps a March-to-October season. Le Grand Bleu, the restaurant of the Hôtel de la Calanque, has its terrace on the cliff above the Cron cove, and the hotel stays open until 6 November 2026. Further east at Gigaro, Le Refuge, first opened under the pines in 1964, buys from local fishermen and serves lunch and dinner five days a week until 31 October.", "where": "Le Comptoir des Saveurs, Cavalaire-sur-Mer; Le Grand Bleu, Cavalaire-sur-Mer; Le Refuge, La Croix-Valmer"}}, {"key": "corniche", "label": "Along the Corniche des Maures", "lead": "Dédé’s bouillabaisse at Le Rayol, and lunch inside the garden of the Mediterraneans.", "story": {"title": "Along the Corniche des Maures", "story": "West of Cavalaire the coast road climbs onto the Corniche des Maures, and its two tables are the ones on this bay that stay open all year. Maurin des Maures in Le Rayol started as a 1920s bar-tabac, and André Delmonte, Dédé, has run it since 1985; his bouillabaisse is ordered the day before, two people minimum. A little further along, the Café des Jardiniers serves lunch only, inside the Domaine du Rayol, the garden Gilles Clément designed for the Conservatoire du littoral. Chef Tom Ortin cooks there every day of the year except Christmas Day, for visitors who have paid to enter the garden.", "where": "Maurin des Maures, Le Rayol-Canadel-sur-Mer; Le Café des Jardiniers, Le Rayol-Canadel-sur-Mer"}}, {"key": "villages", "label": "The hill villages — Gassin and Ramatuelle", "lead": "The Bib Gourmand on Gassin’s rampart, a family table in the vines since 1979, and Italy cooked straight in Ramatuelle.", "story": {"title": "Gassin and Ramatuelle tables", "story": "Up in the hill villages behind the beaches the restaurants keep summer hours. Bello Visto sits on the Barri, Gassin's rampart walk; MICHELIN lists it for its rock octopus casserole and truffle gnocchi, and its 2026 season ran from 24 April to 11 October. Below the village, the Mouret family's La Verdoyante has a terrace that faces the Minuty vines, takes bookings by phone only, and closed on 4 October. In Ramatuelle, La Forge, in the old village forge, has Paolo Amadori from Le Marche making the pasta and bread himself; it opens daily until 1 November.", "where": "Bello Visto, Gassin; La Verdoyante, Gassin; La Forge, Ramatuelle"}}, {"key": "street", "label": "La Rue — off the boat, the Wednesday market, the port glass", "lead": "The fishermen’s crates on the Quai Marc Pajot, the Wednesday square, and the mojito on the port.", "story": {"title": "Off the boat, onto the square", "story": "Cavalaire's cheapest good food is bought standing up. On Quai Marc Pajot the fishermen sell their catch from about ten in the morning, whenever the boats are in and the weather allows; they take rockfish for soup, bream, red mullet and now and then a langouste; the royal right of 1652 that older guides credit for this was not found in any ordinance (the quay's real story is the fold at the top). Every Wednesday of the year the Provençal market fills Place Jean Moulin from 08:30 to 13:00 with tapenade, pissaladière and Maures honey. In the evening Ô Petit Bar, on Rue du Port, pours mojitos looking out over the marina; its tourist listing says it opens every day.", "where": "Fishermen's stand, Cavalaire-sur-Mer; Wednesday market, Cavalaire-sur-Mer; Ô Petit Bar, Cavalaire-sur-Mer"}}];
